// === Tab: structure ===
class Structure {
	constructor() {
		this.spawnPoints = [{ key: 'start', matrix: new p5.Matrix() }]
	}

	place(key) {
		this.spawnPoints.push({
			key,
			matrix: _renderer.uMVMatrix.copy(),
		})
	}

	generate() {
		for (i = 0; i < 30 && this.spawnPoints.length; i++) {
			const spawnIdx = floor(random(this.spawnPoints.length))
			const [spawnPoint] = this.spawnPoints.splice(spawnIdx, 1)
			push()
			applyMatrix(spawnPoint.matrix.mat4)
			this[spawnPoint.key]()
			pop()
		}
	}

	start() {
		const numTowers = random([1, 1, 2, 3])
		for (i = 0; i < numTowers; i++) {
			push()
			translate(random(-400, 400), 0, random(-400, 400))
			this.place('tower')
			pop()
		}
	}

	tower() {
		push()
		rotateY(random([0, 1/4, 1/2, 3/4]) * TWO_PI)
		this.place(random(['cube', 'arch']))
		pop()
	}

	cube() {
		push()
		translate(0, -50, 0)
		model(cube)
		translate(0, -50, 0)
		this.place('block')
		pop()
	}

	plank() {
		push()
		translate(random([59, -50]), -50, 0)
		model(plank)
		translate(0, -50, 0)
		if (random() < 0.5) {
			push()
			translate(random(-50, 50), 0, 0)
			this.place('block')
			pop()
		} else {
			push()
			translate(-50, 0, 0)
			this.place('block')
			pop()
			push()
			translate(50, 0, 0)
			this.place('block')
			pop()
		}
		pop()
	}

	arch() {
		push()
		translate(random([150, -150]), -100, 0)
		model(arch)
		translate(0, -100, 0)
		if (random() < 0.5) {
			push()
			translate(random(-150, 150), 0, 0)
			this.place('block')
			pop()
		} else {
			push()
			translate(-150, 0, 0)
			this.place('block')
			pop()
			push()
			translate(150, 0, 0)
			this.place('block')
			pop()
		}
		pop()
	}

	triPrism() {
		push()
		translate(0, -100, 0)
		model(triPrism)
		pop()
	}

	sphere() {
		push()
		translate(0, -50, 0)
		sphere(50)
		if (random() < 0.75) {
			translate(0, -50, 0)
			this.place('block')
		}
		pop()
	}

	block() {
		push()
		rotateY(random([0, 1/4, 1/2, 3/4]) * TWO_PI)
		rotateY(random(-0.05, 0.05) * PI)
		translate(random(-20, 20), 0, random(-20, 20))
		this.place(random(['cube', 'arch', 'triPrism', 'sphere', 'plank']))
		pop()
	}
}

// === Tab: CSG ===
function geometryToCSG(geom) {
	return CSG.fromPolygons(geom.faces.map((indices) => new CSG.Polygon(
		indices.map((i) => new CSG.Vertex(
			new CSG.Vector(geom.vertices[i].array()),
			geom.vertexNormals[i] ? new CSG.Vector(geom.vertexNormals[i].array()) : undefined
		))
	)))
}

function csgToGeometry(csg) {
	return buildGeometry(() => {
		const polygons = csg.toPolygons()
		for (const polygon of polygons) {
			beginShape()
			for (const vert of polygon.vertices) {
				normal(vert.normal.x, vert.normal.y, vert.normal.z)
				vertex(vert.pos.x, vert.pos.y, vert.pos.z)
			}
			endShape()
		}
	})
}

class CSGWrapper {
	constructor(csg) {
		this.csg = csg
	}

	union(other) {
		return new CSGWrapper(this.csg.union(other.csg))
	}

	subtract(other) {
		return new CSGWrapper(this.csg.subtract(other.csg))
	}

	intersect(other) {
		return new CSGWrapper(this.csg.intersect(other.csg))
	}

	done() {
		return csgToGeometry(this.csg)
	}
}

function csgGeom(geom) {
	return new CSGWrapper(geometryToCSG(geom))
}

