/**
An entry for the #WCCChallenge theme of "improbable architecture"

I just saw The Boy and the Heron, which includes some precariously
stacked blocks like this, so now I'm recreating it through code!

The stacks are made via a simple generating grammar in the `structure`
tab that does no collision detection.

The blocks themselves are made using Evan Wallace's csg.js [1], but
with a wrapper in the `CSG` tab to be able to do booleans with
p5.Geometry inputs. It's barely used in this sketch, but I've wanted
to be able to do that for a while, expect more soon!

The shading includes screen space ambient occlusion via my
p5.FilterRenderer library [2], which uses the depth buffer for this.

[1] https://evanw.github.io/csg.js/
[2] https://github.com/davepagurek/p5.filterRenderer
*/

var arch
var cube
var plank
var triPrism

var tower

var contactShadowRenderer

function setup() {
	createCanvas(windowWidth, windowHeight, WEBGL)
	pixelDensity(1)

	contactShadowRenderer = createContactShadowRenderer()
	contactShadowRenderer.setIntensity(0.4)
	contactShadowRenderer.setBlurRadius(50)
	contactShadowRenderer.setSearchRadius(80)
	contactShadowRenderer.setShadowSamples(20)
	contactShadowRenderer.setBlurSamples(20)
	contactShadowRenderer.setTintColor('#1f6aa1')

	arch = csgGeom(buildGeometry(() => {
		box(400, 200, 100)
	})).subtract(csgGeom(buildGeometry(() => {
		translate(0, 100, 0)
		rotateX(PI/2)
		cylinder(100, 200)
	}))).done()

	cube = buildGeometry(() => {
		box(100)
	})

	plank = buildGeometry(() => {
		box(200, 100, 100)
	})

	triPrism = csgGeom(buildGeometry(() => {
		box(200, 200, 100)
	})).subtract(csgGeom(buildGeometry(() => {
		translate(0, -100, 0)
		rotateZ(PI/4)
		translate(0, -100)
		box(400, 200, 200)
	}))).subtract(csgGeom(buildGeometry(() => {
		translate(0, -100, 0)
		rotateZ(-PI/4)
		translate(0, -100)
		box(400, 200, 200)
	}))).done()
}

var base
function makeTower() {
	if (tower) {
		freeGeometry(tower)
	}
	tower = buildGeometry(() => {
		new Structure().generate()
	})
	tower.normalize()
	tower.clearColors()

	base = max(tower.vertices.map((v) => v.y))
}

var scene = -1
function draw() {
	const nextScene = floor(millis() / 5_000)
	if (scene !== nextScene) {
		scene = nextScene
		makeTower()
	}

	contactShadowRenderer.draw(() => {
		const bgColor = '#DBEBF7'
		background(bgColor)

		noStroke()
		scale(2 * max(width, height) / 800)
		rotateX(PI * -0.1)
		rotateY(millis() * 0.0002)

		push()
		fill(255)
		lights()
		ambientLight(70, 80, 100)
		model(tower)
		pop()

		push()
		translate(0, base, 0)
		rotateX(PI/2)
		fill(bgColor)
		plane(800, 800)
		pop()
	})
}
